import java.io.BufferedInputStream;
import java.io.IOException;

public class Main {
    static class FastScanner {
        private final BufferedInputStream in = new BufferedInputStream(System.in);
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }
    }

    private static String increment(String number) {
        char[] digits = number.toCharArray();
        int i = digits.length - 1;

        while (i >= 0 && digits[i] == '9') {
            digits[i] = '0';
            i--;
        }

        if (i < 0) {
            return "1" + new String(digits);
        }

        digits[i]++;
        return new String(digits);
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();

        StringBuilder input = new StringBuilder(n);
        for (int i = 0; i < n; i++) {
            input.append((char) ('0' + fs.nextInt()));
        }

        String best = null;

        for (int startLength = 1; startLength <= n; startLength++) {
            if (input.charAt(0) == '0') break;

            String current = input.substring(0, startLength);
            int pos = startLength;
            boolean valid = true;

            while (pos < n) {
                current = increment(current);
                if (pos + current.length() > n
                        || !input.toString().regionMatches(pos, current, 0, current.length())) {
                    valid = false;
                    break;
                }
                pos += current.length();
            }

            if (valid && pos == n) {
                if (best == null || currentCandidateIsSmaller(input, startLength, best)) {
                    best = input.substring(0, startLength);
                }
            }
        }

        System.out.println(best);
    }

    private static boolean currentCandidateIsSmaller(StringBuilder input, int length, String best) {
        if (length != best.length()) return length < best.length();
        for (int i = 0; i < length; i++) {
            char a = input.charAt(i);
            char b = best.charAt(i);
            if (a != b) return a < b;
        }
        return false;
    }
}
